// Acceptance criteria for SHOP-3. CI runs these cases and 12 more it does not show.
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { JSDOM } from "jsdom";

const { document } = new JSDOM(readFileSync("templates/filter-form-labels.html", "utf8")).window;
const squash = (text) => (text ?? "").replace(/\s+/g, " ").trim();

/** The name a screen reader announces: aria-labelledby, aria-label, then the label. */
function label(element) {
  const ids = element.getAttribute("aria-labelledby");
  if (ids) return squash(ids.split(/\s+/).map((id) => document.getElementById(id)?.textContent).join(" "));
  if (element.hasAttribute("aria-label")) return squash(element.getAttribute("aria-label"));
  const tied = element.id && document.querySelector(`label[for="${element.id}"]`);
  const owner = tied || element.closest("label");
  return owner ? squash(owner.textContent) : null;
}

function read(selector, how) {
  const matches = [...document.querySelectorAll(selector)];
  if (how === "count") return matches.length;
  if (how === "text") return matches.map((element) => squash(element.textContent));
  if (how === "label") return matches.map(label);
  return matches.map((element) => element.getAttribute(how));
}

// [selector, what to read, expected]: "count", "text", "label" (the accessible
// name a screen reader announces) or an attribute name.
const cases = [
  ["form input[type=checkbox]", "name", ["in-stock","on-sale"]],
  ["form input[type=checkbox]", "id", ["filter-in-stock","filter-on-sale"]],
  ["form input[type=checkbox]", "label", ["in-stock","on-sale"]],
  ["form label", "text", ["in-stock","on-sale"]],
];

describe("templates/filter-form-labels.html", () => {
  it.each(cases)("%s → %s", (selector, how, expected) => {
    expect(read(selector, how)).toEqual(expected);
  });
});

src/cache_index.cpp.text:
// cache_index.cpp: the response cache's index, from a request's key to the slot that holds
// its response in the arena.
//
// Open addressing with linear probing over a fixed array of slots, sized once at startup from
// cache.index_slots. This replaced the std::unordered_map index on Thursday (#412): that
// allocated a node on every insert, about 9% of CPU on the edge flame graphs at peak.
#include <cstddef>
#include <string>
#include <vector>

namespace {

class CacheIndex {
  public:
    explicit CacheIndex(std::size_t slots) : slots_(slots) {}

    // Stores value under key. False when every slot is taken: the response is then served
    // without being cached.
    bool put(int key, int value) {
        if (slots_.empty()) return false;
        std::size_t i = home(key);
        for (std::size_t probes = 0; probes < slots_.size(); probes++) {
            Slot &slot = slots_[i];
            if (slot.state == State::Empty) {
                slot = Slot{State::Full, key, value};
                return true;
            }
            if (slot.key == key) {
                slot.value = value;
                return true;
            }
            i = next(i);
        }
        return false;
    }

    // The value stored under key, or -1 on a miss.
    int get(int key) const {
        const Slot *slot = find(key);
        return slot ? slot->value : -1;
    }

    // Purges key, if it is there.
    void erase(int key) {
        Slot *slot = const_cast<Slot *>(find(key));
        if (slot) *slot = Slot{};
    }

  private:
    enum class State : unsigned char { Empty, Full };
    struct Slot {
        State state = State::Empty;
        int key = 0;
        int value = 0;
    };

    // Keys are already hashes of the request (method, host, path, Vary headers).
    std::size_t home(int key) const { return static_cast<unsigned>(key) % slots_.size(); }
    std::size_t next(std::size_t i) const { return (i + 1) % slots_.size(); }

    const Slot *find(int key) const {
        if (slots_.empty()) return nullptr;
        std::size_t i = home(key);
        for (std::size_t probes = 0; probes < slots_.size(); probes++) {
            const Slot &slot = slots_[i];
            if (slot.state == State::Empty) return nullptr;
            if (slot.key == key) return &slot;
            i = next(i);
        }
        return nullptr;
    }

    std::vector<Slot> slots_;
};

}  // namespace

// One line of a cache log: {"put", key, value}, {"get", key} or {"erase", key}.
struct Op {
    std::string name;
    int key;
    int value;
};

// Replays a cache log against an index with the given number of slots and returns what each
// get found, -1 for a miss. edgectl cache replay and the tests use it.
std::vector<int> cache_index(int slots, const std::vector<Op>& ops) {
    CacheIndex index(static_cast<std::size_t>(slots));
    std::vector<int> found;
    for (const Op &op : ops) {
        if (op.name == "put")
            index.put(op.key, op.value);
        else if (op.name == "erase")
            index.erase(op.key);
        else if (op.name == "get")
            found.push_back(index.get(op.key));
    }
    return found;
}

