// Acceptance criteria for EDGE-7. CI runs these cases and 12 more it does not show.
// Each case runs the program once: the arguments go to mm_call as JSON, and what it
// returns is compared with the expected JSON.

#include <string>
#include <vector>
#include "mm_json.h"

struct Op {
    std::string name;
    int key;
    int value;
};
std::vector<int> cache_index(int slots, const std::vector<Op>& ops);

// [slots, [[name, key, value?], ...]] → what each get found.
mm_value *mm_call(const mm_value *args) {
    std::vector<Op> ops;
    const mm_value *list = mm_at(args, 1);
    for (size_t i = 0; i < mm_length(list); i++) {
        const mm_value *op = mm_at(list, i);
        ops.push_back({mm_string(mm_at(op, 0)), (int)mm_integer(mm_at(op, 1)),
                       (int)mm_integer(mm_at(op, 2))});
    }
    mm_value *result = mm_new_array();
    for (int got : cache_index((int)mm_integer(mm_at(args, 0)), ops))
        mm_push(result, mm_new_integer(got));
    return result;
}

/* Arguments and expected result, as JSON. */
static const struct { const char *args; const char *expected; } cases[] = {
    {"[8,[[\"put\",1,100],[\"put\",2,200],[\"get\",1],[\"get\",2],[\"get\",3]]]", "[100,200,-1]"},
    {"[8,[[\"put\",3,30],[\"put\",11,110],[\"put\",19,190],[\"erase\",3],[\"get\",11],[\"get\",19],[\"get\",3]]]", "[110,190,-1]"},
    {"[8,[[\"put\",5,50],[\"put\",5,55],[\"get\",5],[\"erase\",5],[\"get\",5],[\"erase\",5],[\"get\",5]]]", "[55,-1,-1]"},
    {"[2,[[\"put\",0,1],[\"put\",1,2],[\"put\",2,3],[\"get\",2],[\"erase\",0],[\"put\",2,3],[\"get\",2],[\"get\",1]]]", "[-1,3,2]"},
